import type { ScriptContext, ScriptResult } from "@gtm-factory/core";

/** Reads our mailboxes and matches each answer to the message it answers. */
export default function run(ctx: ScriptContext): ScriptResult {
  ctx.get("message_queued");
  const r = ctx.vendor.call("imap.read");
  return r.ok ? { content: { thread: true } } : null;
}

import type { ScriptContext, ScriptResult } from "@gtm-factory/core";

/** Reads the mailbox the message left from and matches each answer to the message it answers. */
export default function run(ctx: ScriptContext): ScriptResult {
  const queued = ctx.get("message_queued");
  const account = String(queued.content.account ?? "");
  const r = ctx.vendor.call("imap.read", { account });
  return r.ok ? { content: { thread: true, account, via: "read" } } : null;
}

import type { ScriptContext, ScriptResult } from "@gtm-factory/core";

/** Sends a LinkedIn connection with a note written from the template; an answer is a reply. */
export default function run(ctx: ScriptContext): ScriptResult {
  const lead = ctx.get("lead_identified");
  const template = ctx.get("template_written");
  const llm = ctx.get("llm_completion");
  ctx.get("rating");
  const r = ctx.vendor.call("linkedin.connect", { lead: lead.subject, template: template.content.text, model: llm.content.model });
  return r.ok ? { content: { channel: "LinkedIn", text: String(r.data.text ?? "") } } : null;
}

import type { ScriptContext, ScriptResult } from "@gtm-factory/core";

/** Sends a LinkedIn connection with a note written from the template, from the brand's profile with this script's role; an answer is a reply. */
export default function run(ctx: ScriptContext): ScriptResult {
  const lead = ctx.get("lead_identified");
  const template = ctx.get("template_written");
  const llm = ctx.get("llm_completion");
  ctx.get("rating");
  const profiles = ctx.accounts("LinkedIn", String(ctx.tactics.account_role ?? "AI agent")).filter((a) => a.status === "connected");
  if (profiles.length === 0) return null;
  const from = profiles.reduce((best, a) => (a.sentToday < best.sentToday ? a : best));
  const r = ctx.vendor.call("linkedin.connect", { from: from.address, lead: lead.subject, template: template.content.text, model: llm.content.model });
  return r.ok ? { content: { channel: "LinkedIn", account: from.id, via: "read", text: String(r.data.text ?? "") } } : null;
}

import type { ScriptContext, ScriptResult } from "@gtm-factory/core";

/** Reads our mailboxes and matches each answer to the follow-up it answers. */
export default function run(ctx: ScriptContext): ScriptResult {
  ctx.get("follow_up_queued");
  const r = ctx.vendor.call("imap.read");
  return r.ok ? { content: { thread: true } } : null;
}

import type { ScriptContext, ScriptResult } from "@gtm-factory/core";

/**
 * Writes to the person on WhatsApp from one of the brand's numbers with the role
 * this script carries (its "Account role" tactic), the one that sent the least
 * today. An answer is a reply.
 */
export default function run(ctx: ScriptContext): ScriptResult {
  const lead = ctx.get("lead_identified");
  const template = ctx.get("template_written");
  const llm = ctx.get("llm_completion");
  ctx.get("rating");
  const numbers = ctx.accounts("WhatsApp", String(ctx.tactics.account_role ?? "AI agent")).filter((a) => a.status === "connected");
  if (numbers.length === 0) return null;
  const from = numbers.reduce((best, a) => (a.sentToday < best.sentToday ? a : best));
  const r = ctx.vendor.call("whatsapp.send", { from: from.address, to: lead.subject, template: template.content.text, model: llm.content.model });
  return r.ok ? { content: { channel: "WhatsApp", account: from.id, via: "read", text: String(r.data.text ?? "") } } : null;
}
